if(document.modelContext?.registerTool){const lifecycle=new AbortController();window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});try{Promise.resolve(document.modelContext.registerTool({name:'navigate_vpn_section',description:'Открыть раздел приложения. Не меняет состояние подключения.',inputSchema:{type:'object',properties:{section:{type:'string',enum:['overview','servers','rules','dns','connections','settings','help']}},required:['section'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['overview','servers','rules','dns','connections','settings','help'].includes(input.section))throw Error('Unknown section');changePage(input.section);return {section:page}}},{signal:lifecycle.signal})).catch(()=>{})}catch{}}

