function policiesModal(){const policyRow=p=>`<div class="dns-policy-row"><input class="form-input" name="domain" aria-label="Домен или шаблон" value="${esc(p.domain||'')}" placeholder="+.company.example"><input class="form-input" name="server" aria-label="DNS-сервер" value="${esc(p.server||'')}" placeholder="10.20.0.53"><button type="button" class="icon-button" data-remove-dns-row aria-label="Удалить правило">${icon('trash')}</button></div>`;showModal('DNS для отдельных доменов','Каждая строка связывает домен с конкретным DNS-сервером.',`<div class="dns-editor-wide dns-policy-editor"><div class="dns-policy-help"><p><strong>Домен</strong><span>+.company.example включает поддомены.<br>portal.company.example задаёт точный адрес.</span></p><p><strong>DNS-сервер</strong><span>IP, IP:порт или https://…/dns-query.<br>Подойдёт DNS другого VPN, например Cisco.</span></p></div><div class="dns-policy-labels"><span>Домен или шаблон</span><span>DNS-сервер</span></div><div id="dns-policy-rows">${(state.dns.policies.length?state.dns.policies:[{}]).map(policyRow).join('')}</div><button type="button" class="button" id="add-dns-row">${icon('plus')}Добавить строку</button><p class="dns-input-help">Несколько DNS для домена: добавьте строки с одинаковым доменом. Пустой список использует общие DNS.</p></div>`,()=>{const policies=[];for(const row of document.querySelectorAll('.dns-policy-row')){const domain=row.querySelector('[name=domain]').value.trim(),server=row.querySelector('[name=server]').value.trim();if(!domain&&!server)continue;if(!domain||/\s|:\/\//.test(domain))throw Error('Укажите домен без протокола и пробелов.');if(!dnsValid(server))throw Error('Укажите корректный DNS для '+domain);policies.push({domain,server});}state.dns.policies=policies;});document.querySelector('#add-dns-row').onclick=()=>{const rows=document.querySelector('#dns-policy-rows');rows.insertAdjacentHTML('beforeend',policyRow({}));rows.lastElementChild.querySelector('input').focus()};document.querySelector('#dns-policy-rows').onclick=e=>e.target.closest('[data-remove-dns-row]')?.closest('.dns-policy-row').remove();}
function aboutModal(){showModal(esc(window.APP_PRODUCT.name),'Версия '+esc(window.APP_PRODUCT.version),`<p class="delete-text">Клиент Mihomo для Windows и macOS.</p><p class="delete-text" style="margin-top:14px">Настройки хранятся на этом устройстве. Резервная копия содержит серверы, подписки, правила, DNS и ключи доступа.</p><div class="inline-help">${icon('book')}<a href="https://wiki.metacubex.one/" target="_blank" rel="noreferrer">Документация Mihomo ↗</a></div>`,()=>{},'Понятно')}
document.addEventListener('click',e=>{const b=e.target.closest('[data-window]');if(!b||window.APP_DESKTOP)return;const w=document.querySelector('#app-window');if(b.dataset.window==='maximize'){w.classList.remove('minimized');w.classList.toggle('maximized');b.setAttribute('aria-label',w.classList.contains('maximized')?'Восстановить размер окна':'Развернуть окно')}if(b.dataset.window==='minimize'){w.classList.toggle('minimized');b.setAttribute('aria-label',w.classList.contains('minimized')?'Восстановить окно':'Свернуть окно')}if(b.dataset.window==='close'){w.classList.add('closed');document.querySelector('#restore-window').hidden=false}});
document.querySelector('#restore-window').onclick=()=>{document.querySelector('#app-window').classList.remove('closed','minimized');document.querySelector('#restore-window').hidden=true};
// Embedded modal controls should never submit the enclosing form.
const modalObserver=new MutationObserver(()=>modal.querySelectorAll('button[data-action],button[data-toggle]').forEach(b=>b.type='button'));modalObserver.observe(document.querySelector('#modal-body'),{childList:true,subtree:true});

window.addEventListener('app-error',event=>toast(event.detail));


// Keep the connection button mounted while telemetry changes so hover/focus stay stable.
function updateOverview(){
 if(page!=='overview')return;
 const template=document.createElement('template');template.innerHTML=overview();
 for(const selector of ['.connection-caption','.power-label','.uptime','.server-picker','.connection-ip','.traffic-surface','.status-foot']){
  const target=document.querySelector(selector),source=template.content.querySelector(selector);
  if(target&&source&&target.innerHTML!==source.innerHTML)target.innerHTML=source.innerHTML;
 }
 const button=document.querySelector('.power-button'),source=template.content.querySelector('.power-button');
 if(button&&source){
  button.className=source.className;button.disabled=source.disabled;
  button.setAttribute('aria-label',source.getAttribute('aria-label'));
  if(connectionPhase)button.setAttribute('aria-busy','true');else button.removeAttribute('aria-busy');
  if(button.innerHTML!==source.innerHTML)button.innerHTML=source.innerHTML;
 }
 document.querySelector('.connection-surface')?.classList.toggle('off',!connected);
}
async function refreshStatus(force=false){
 if(!window.APP_API||(!force&&busy)||polling)return;
 polling=true;
 try {
  const next=JSON.parse(await window.APP_API.Status());
  coreStatus=next;connected=next.running;started=next.started||0;
  void latencyMonitor.tick(connected,String(started)+':'+latencyURL(),coreStatus.activeServer||state.selected);
  void refreshServerLatency();
  if(!modal.open&&savesPending===0&&next.revision>(persistedState.revision||0)){state=JSON.parse(await window.APP_API.LoadConfig());persistedState=structuredClone(state);render();}
  traffic=sample(traffic,next);history.push(traffic);if(history.length>1800)history.shift();
  connections=(next.connections||[]).map(c=>({...c,letter:(c.app||'?')[0],down:bytes(c.down),up:bytes(c.up)}));
  if(!busy&&!modal.open&&!document.querySelector('[aria-expanded="true"]')&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement?.tagName)&&(page==='overview'||page==='connections')){if(page==='overview')updateOverview();else render();}
 } catch(error){coreStatus.error=error.message;} finally{polling=false;}
}
async function runAction(action,button){
 if(busy)return;
 if(!window.APP_API){toast('Откройте desktop-приложение');return;}
 busy=true;document.body.classList.add('operation-busy');
 const previous=button?.innerHTML;
 const isRestart=button?.dataset.action==='restart-core';
 const isConnection=button?.dataset.action==='connect'||isRestart;
 if(isConnection){connectionPhase=isRestart?'Перезапуск…':coreStatus.running?'Отключение…':'Подключение…';updateOverview();}
 if(button&&!isConnection){button.style.minWidth=button.getBoundingClientRect().width+'px';button.disabled=true;button.setAttribute('aria-busy','true');button.innerHTML=`<span class="button-spinner" aria-hidden="true"></span>${button.dataset.action==='install-core'?'Обновление…':'Выполняется…'}`;}
 let message='';
 try{await saveChain;message=await action()||'';}catch(error){message=error.message;coreStatus.error=error.message;}
 finally{await refreshStatus(true);connectionPhase='';busy=false;document.body.classList.remove('operation-busy');if(button?.isConnected){button.innerHTML=previous;button.disabled=false;button.removeAttribute('aria-busy');button.style.minWidth='';}if(!modal.open)render();if(typeof message==='string'&&message)toast(message);}
}

document.addEventListener('click',event=>{
 const button=event.target.closest('button');if(!button)return;const d=button.dataset;
 if(busy&&!d.window){event.preventDefault();event.stopImmediatePropagation();return;}
 if(d.action==='latency'){event.preventDefault();event.stopImmediatePropagation();void refreshAllServerLatency();return;}
 const actions={
  'import-sets':importRouteSets,
  'export-sets':async()=>{if(await window.APP_API.ExportRouteSets(''))toast('Наборы экспортированы');},
  'work-preset':async()=>{const item=JSON.parse(await window.APP_API.WorkPreset());item.id=crypto.randomUUID();setModal(item);},
  'import-yaml':async()=>{const data=await window.APP_API.ImportYAML();if(!data)return;const result=JSON.parse(data);showModal('Импорт YAML','Проверьте изменения перед заменой текущих настроек.',`<p>${result.config.servers.length} серверов · ${result.config.rules.length} правил</p><ul>${result.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`,()=>{state=result.config;state.revision=persistedState.revision;},'Импортировать');},
  export:async()=>{if(await window.APP_API.ExportBackup())toast('Резервная копия сохранена');},
  import:async()=>{const data=await window.APP_API.ImportBackup();if(!data)return;const imported=JSON.parse(data);showModal('Импортировать настройки?','Текущая конфигурация будет заменена.',`<p class="delete-text">${imported.servers.length} серверов, ${imported.rules.length} правил, ${imported.subscriptions.length} подписок.</p>`,()=>{state=imported;state.revision=persistedState.revision;},'Импортировать');},
  connect:async()=>{if(coreStatus.running){await window.APP_API.Stop();return;}if(!state.servers.length){changePage('servers');toast('Добавьте сервер или подписку');return;}if(!coreStatus.installed&&!coreStatus.bundled){showModal('Первое подключение','Для этой сборки нужно скачать ядро Mihomo. После установки подключение продолжится.', '<p>Загрузка с официального GitHub. Файл проверяется по SHA-256.</p>',async()=>{await window.APP_API.InstallCore();await window.APP_API.Start();},'Скачать и подключиться');return;}if(!coreStatus.installed)toast('Подготовка встроенного ядра…');await window.APP_API.Start();},
  'restart-core':async()=>{await window.APP_API.Stop();await window.APP_API.Start();return 'Ядро перезапущено';},
  'install-core':async()=>{await window.APP_API.InstallCore();return 'Ядро обновлено';},
  'recover-proxy':async()=>{await window.APP_API.RecoverProxy();toast('Настройки прокси восстановлены');},
  yaml:async()=>showModal('Конфигурация Mihomo','Контроллер и его секрет назначаются при запуске.',`<pre class="code-preview">${esc(await yamlPreview())}</pre>`,()=>{},'Закрыть'),
  'log-copy':async()=>logView.copy(),
  'log-export':async()=>{if(await window.APP_API.ExportLogs())toast('Журнал сохранён');},
  'log-clear':async()=>showModal('Очистить журналы?','Все сохранённые файлы журнала будут удалены.','',async()=>{await window.APP_API.ClearLogs();await logView.refresh();},'Очистить'),
  'log-pause':async()=>{logView.toggle();},
  'log-settings':async()=>logView.settings(),
 };
 let action=actions[d.action];
 if(d.exportSet)action=async()=>{if(await window.APP_API.ExportRouteSets(d.exportSet))toast('Набор экспортирован');};
 if(d.updateSubscription)action=async()=>{state=JSON.parse(await window.APP_API.UpdateSubscription(d.updateSubscription));persistedState=structuredClone(state);toast('Подписка обновлена');};
 if(action){event.preventDefault();event.stopImmediatePropagation();void runAction(action,button);}
},true);
if(loadError)toast(loadError);
await refreshStatus();
setInterval(refreshStatus,2000);

function setsPanel(){const sets=state.sets||[];return `<section class="native-settings route-sets"><div class="setting-row"><div><strong>Наборы маршрутизации</strong><p>Можно включить несколько. Порядок сверху вниз, перед отдельными правилами.</p></div><div class="actions route-set-actions">${btn('Импорт','import-sets','upload','small ghost')}${sets.length?btn('Экспорт','export-sets','download','small ghost'):''}${btn('Добавить набор','add-set','plus')}</div></div>${sets.length?sets.map((s,i)=>`<div class="setting-row route-set-row ${s.enabled?'':'inactive'}"><div class="rule-order"><span>${String(i+1).padStart(2,'0')}</span><button class="icon-button" data-move-set="${esc(s.id)}" data-direction="-1" aria-label="Поднять набор ${esc(s.name)}" ${i===0?'disabled':''}>${icon('up')}</button><button class="icon-button" data-move-set="${esc(s.id)}" data-direction="1" aria-label="Опустить набор ${esc(s.name)}" ${i===sets.length-1?'disabled':''}>${icon('down')}</button></div><div class="route-set-description"><strong>${esc(s.name)}</strong><p>Домены: ${s.domains.length}${s.keywords?.length?' · Части домена: '+s.keywords.length:''} · DNS: ${s.resolvers.length} · Подсети: ${s.cidrs.length} · Процессы: ${(s.processes||[]).length}</p></div>${badge(s.action)}<div class="table-actions"><button class="switch ${s.enabled?'on':''}" role="switch" aria-checked="${s.enabled}" aria-label="Набор ${esc(s.name)}" data-toggle-set="${esc(s.id)}"></button><button class="icon-button" data-export-set="${esc(s.id)}" aria-label="Экспортировать ${esc(s.name)}">${icon('download')}</button><button class="icon-button" data-edit-set="${esc(s.id)}" aria-label="Изменить набор ${esc(s.name)}">${icon('edit')}</button><button class="icon-button" data-remove-set="${esc(s.id)}" aria-label="Удалить набор ${esc(s.name)}">${icon('trash')}</button></div></div>`).join(''):'<p class="route-sets-empty">Объедините домены, процессы, DNS и подсети, чтобы включать их одним переключателем.</p>'}</section>`}

function setModal(item){editSet({item,state,getState:()=>state,showModal,field,selectField,esc,upsert})}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.editSet)setModal(state.sets.find(s=>s.id===d.editSet));if(d.removeSet)confirmDelete('набор',()=>state.sets=state.sets.filter(s=>s.id!==d.removeSet));if(d.action==='add-set')setModal();});

function rulesPage(){return `<section class="rules-workspace">${routingRulesPage()}</section>`}
function routingNetworkPage(){const exclusions=state.settings.routeExclusions||[];return `<section class="rules-network"><div class="native-settings rules-exclusions">${row('Подсети вне адаптера','Обход TUN: трафик направляется по маршрутам ОС.',btn('Изменить','route-exclusions','edit'))}<div class="tun-exclusions">${exclusions.length?exclusions.map(cidr=>`<code>${esc(cidr)}</code>`).join(''):'Нет отдельных исключений'}</div></div><div class="native-settings rules-processing">${row('Определение домена','Sniffer для HTTP, TLS и QUIC',toggle('settings.sniffer',state.settings.sniffer))}${row('IPv6','Соединения и DNS-ответы IPv6',toggle('settings.ipv6',state.settings.ipv6))}</div></section>`}
document.addEventListener('click',e=>{const d=e.target.closest('button')?.dataset;if(!d)return;if(d.toggleSet){const item=state.sets.find(s=>s.id===d.toggleSet);if(item){item.enabled=!item.enabled;save();render();}}if(d.moveSet){const i=state.sets.findIndex(s=>s.id===d.moveSet),j=i+Number(d.direction);if(i>=0&&j>=0&&j<state.sets.length){[state.sets[i],state.sets[j]]=[state.sets[j],state.sets[i]];save();render();}}});

document.addEventListener('click',event=>{const anchor=event.target.closest('a[href]');if(!anchor||!window.APP_API)return;const url=new URL(anchor.href,location.href);if(!['http:','https:'].includes(url.protocol)||url.origin===location.origin)return;event.preventDefault();event.stopImmediatePropagation();void window.APP_API.OpenExternalURL(url.href).catch(error=>toast(error.message));},true);

function latencySettingsModal(){showModal('Проверка задержки','Запрос через проверяемый VPN-сервер. Общий адрес для замеров и автоматического резерва. Замеры меняются сразу; проверка резерва — после переподключения.',field('URL проверки','url',latencyURL(),'Полный HTTP/HTTPS URL страницы с быстрым ответом. Это веб-запрос, а не DNS-запрос или ICMP-пинг.','url'),f=>{const address=f.get('url').trim();const u=new URL(address);if(!['http:','https:'].includes(u.protocol)||u.username||u.password||u.hash)throw Error('Укажите HTTP/HTTPS URL без логина и фрагмента');state.settings.latencyURL=address;for(const server of state.servers)server.latency=0;})}

function vpnGroupMode(){return state.settings.groupMode||(state.settings.failover===false?'select':'fallback')}
function vpnGroupLabel(){return {'select':'Ручной выбор','fallback':'Резерв по приоритету','url-test':'Минимальная задержка','load-balance':'Балансировка соединений'}[vpnGroupMode()]}
function ruleDestination(r){if(r.action!=='PROXY'||!r.target)return '';return r.target==='@fastest'?'Минимальная задержка':state.servers.find(s=>s.id===r.target)?.name||'Сервер удалён · блокировка'}
function healthFields(){return `<section class="group-health" id="group-health"><h3 id="health-heading">Проверка серверов</h3>${field('Адрес для проверки серверов','healthURL',latencyURL(),'Запрос идёт через проверяемый VPN. Недоступность этого адреса тоже влияет на результат.','url')}<div class="health-timing-grid"><div id="health-interval-field">${field('Проверять серверы каждые, сек.','healthInterval',state.settings.healthInterval||30,'Период фоновых проверок · от 10 до 3600 сек.','number')}</div>${field('Ждать ответа не дольше, мс','healthTimeout',state.settings.healthTimeout||5000,'После этого времени попытка считается неудачной · от 1000 до 30000 мс.','number')}<div id="health-tolerance-field">${field('Менять сервер при выигрыше, мс','healthTolerance',state.settings.healthTolerance??50,'Например, 50: не переключаться ради улучшения с 120 до 100 мс.','number')}</div></div><p id="fastest-rule-note" class="dns-input-help" hidden>Допуск и фоновые проверки также используются отдельными правилами с выбором по минимальной задержке.</p><div id="health-lazy-field"><label class="set-toggle"><span><strong>Пауза проверок, пока группа не используется</strong><small>Включено: если трафик не направляется в эту группу, ядро может пропускать её проверки. Выключено: проверяет постоянно. Замеры в списке серверов работают отдельно.</small></span><input type="checkbox" role="switch" name="healthLazy" ${state.settings.healthLazy?'checked':''}><span class="set-toggle-track" aria-hidden="true"></span></label></div></section>`}

function groupHealthModal(){failoverSettingsModal();requestAnimationFrame(()=>document.querySelector('#group-health')?.scrollIntoView({block:'start'}))}
function orderedServers(){const ids=[state.selected,...(state.settings.serverOrder||[]),...state.servers.map(s=>s.id)];return [...new Set(ids)].map(id=>state.servers.find(s=>s.id===id)).filter(Boolean)}
function failoverSettingsModal(){
 const ordered=orderedServers();
 showModal('Выбор VPN-сервера','Применение перезапустит активное соединение с новыми настройками.',selectField('Режим группы','groupMode',[['select','Ручной выбор'],['fallback','Резерв по приоритету · fallback'],['url-test','Минимальная задержка · url-test'],['load-balance','Балансировка соединений · load-balance']],vpnGroupMode())+`<p class="group-mode-description" id="group-mode-description"></p><div id="balance-options">${selectField('Стратегия балансировки','balanceStrategy',[['consistent-hashing','Один адрес назначения — один сервер'],['round-robin','Соединения по очереди'],['sticky-sessions','Закреплять источник и назначение на 10 минут']],state.settings.balanceStrategy||'consistent-hashing')}</div>`+healthFields()+`<div class="failover-order" id="failover-order">${ordered.map(s=>`<div class="setting-row" data-priority-id="${esc(s.id)}"><span class="priority-number"></span><div class="priority-server"><div class="priority-name-line"><strong>${esc(s.name)}</strong><span class="priority-source">${esc(subscriptionName(s))}</span></div><div class="priority-meta">${serverBadges(s)}<span class="priority-address">${esc(s.host)}:${esc(s.port)}</span></div></div><div class="table-actions"><button type="button" class="icon-button" data-priority-move="-1" aria-label="Поднять ${esc(s.name)}">${icon('up')}</button><button type="button" class="icon-button" data-priority-move="1" aria-label="Опустить ${esc(s.name)}">${icon('down')}</button></div></div>`).join('')||'<p class="muted">Сначала добавьте серверы.</p>'}</div>`,async f=>{
  for(const [key,min,max] of [['healthInterval',10,3600],['healthTimeout',1000,30000],['healthTolerance',0,1000]]){const n=Number(f.get(key));if(!Number.isInteger(n)||n<min||n>max)throw Error('Проверьте диапазон числовых параметров проверки');}state.settings.groupMode=f.get('groupMode');state.settings.failover=state.settings.groupMode!=='select';state.settings.latencyURL=f.get('healthURL').trim();state.settings.healthInterval=Number(f.get('healthInterval'));state.settings.healthTimeout=Number(f.get('healthTimeout'));state.settings.healthTolerance=Number(f.get('healthTolerance'));state.settings.healthLazy=f.has('healthLazy');state.settings.balanceStrategy=f.get('balanceStrategy');state.settings.serverOrder=[...document.querySelectorAll('[data-priority-id]')].map(el=>el.dataset.priorityId);if(state.settings.serverOrder.length)state.selected=state.settings.serverOrder[0];
  if(!await save())throw Error(lastSaveError);
  if(coreStatus.running){await window.APP_API.Stop();await window.APP_API.Start();}
  await refreshStatus();return false;
 },'Применить');
 const list=document.querySelector('#failover-order');
 const groupMode=document.querySelector('#modal-form').elements.groupMode;
 const updateMode=()=>{
 const mode=groupMode.value,auto=mode!=='select',fastRules=state.rules.some(r=>r.action==='PROXY'&&r.target==='@fastest'),fast=mode==='url-test'||fastRules;
 document.querySelector('#group-mode-description').textContent={select:'Используется первый сервер в списке. Автоматического переключения нет.',fallback:'Используется первый доступный сервер по порядку. При отказе — следующий; после восстановления — возврат к приоритетному.', 'url-test':'Выбирается сервер с наименьшей задержкой до проверочного адреса. Задержка до других сайтов и сервисов может отличаться.', 'load-balance':'Новые соединения распределяются между доступными серверами. Одно соединение использует один сервер.'}[mode];
 document.querySelector('#balance-options').hidden=mode!=='load-balance';
 document.querySelector('#health-heading').textContent=auto?'Параметры проверки серверов':'Замер задержки в интерфейсе';
 document.querySelector('#health-interval-field').hidden=!(auto||fastRules);
 document.querySelector('#health-tolerance-field').hidden=!fast;
 document.querySelector('#health-lazy-field').hidden=!(auto||fastRules);
 document.querySelector('#fastest-rule-note').hidden=!(fastRules&&mode!=='url-test');
 document.querySelector('.health-timing-grid').style.gridTemplateColumns=`repeat(${1+Number(auto||fastRules)+Number(fast)}, minmax(0, 1fr))`;
 };groupMode.addEventListener('change',updateMode);updateMode();
 const update=()=>{[...list.children].forEach((el,i)=>{if(!el.dataset.priorityId)return;el.querySelector('.priority-number').textContent=String(i+1)+'.';el.querySelector('[data-priority-move="-1"]').disabled=i===0;el.querySelector('[data-priority-move="1"]').disabled=i===list.children.length-1})};
 list.onclick=e=>{const b=e.target.closest('[data-priority-move]');if(!b)return;const row=b.closest('[data-priority-id]');if(b.dataset.priorityMove==='-1'&&row.previousElementSibling)list.insertBefore(row,row.previousElementSibling);if(b.dataset.priorityMove==='1'&&row.nextElementSibling)list.insertBefore(row.nextElementSibling,row);update()};update();
}

async function applyStatusSetting(key,value){
 await runAction(async()=>{
  connectionPhase=connected?'Применение…':'';
  state.settings[key]=value;render();
  if(!await save())throw Error(lastSaveError);
 });
}

async function importRouteSets(){
 const data=await window.APP_API.ImportRouteSets();if(!data)return;
 const incoming=JSON.parse(data),added=newRouteSets(state.sets||[],incoming);
 if(!added.length){toast('Эти наборы уже добавлены');return;}
 const skipped=incoming.length-added.length;
 showModal('Импорт наборов маршрутизации',`Будет добавлено: ${added.length}${skipped?' · Уже есть: '+skipped:''}. Существующие наборы сохранятся.`,
 `<div class="route-set-import">${added.map(set=>`<section class="route-set-preview"><div class="route-set-preview-heading"><strong>${esc(set.name)}</strong><span>${set.enabled?'Включён':'Выключен'} · ${esc({DIRECT:'Напрямую',PROXY:'Через VPN',REJECT:'Блокировать'}[set.action])}</span></div><dl>${[['Домены',set.domains],['Части домена',set.keywords],['DNS',set.resolvers],['Подсети',set.cidrs],['Приложения',set.processes]].filter(([,values])=>values?.length).map(([label,values])=>`<div><dt>${label}</dt><dd>${values.map(esc).join(' · ')}</dd></div>`).join('')}</dl><p>${set.realIP?'Реальные IP':'Общий режим DNS'} · ${set.bypassTUN?'Обход TUN включён':'Без исключений TUN'}</p></section>`).join('')}</div><p class="dns-input-help">Наборы добавятся в конец списка. Для применения перезапустите ядро.${state.settings.mode!=='rule'?' Для правил доменов и процессов выберите на странице «Статус» режим «По правилам».':''}</p>`,()=>{
  state.sets=[...(state.sets||[]),...newRouteSets(state.sets||[],added)];
 },'Импортировать');
}
